def transform(grid):
    h, w = len(grid), len(grid[0])

    # Each uniform row marks a color at its position in a repeating
    # vertical sequence. Use the non-background colors in row order.
    from collections import Counter
    row_colors = [row[0] for row in grid]
    background = Counter(row_colors).most_common(1)[0][0]

    marks = {}
    for r, color in enumerate(row_colors):
        if color != background:
            marks[r] = color

    seq = []
    for color in marks.values():
        if color not in seq:
            seq.append(color)

    # Preserve the marked stripe colors as a repeating row pattern.
    if not seq:
        seq = [background]
    return [[seq[r % len(seq)]] * w for r in range(h)]
